#include "replay.hpp"
#include <deque>
#include <algorithm>
#include <stdexcept>
namespace hr {
struct Replay::Snapshot {std::filesystem::path folder;std::vector<std::filesystem::path> files;~Snapshot(){std::error_code ec;std::filesystem::remove_all(folder,ec);}};
namespace {
unsigned long long process_birth(HANDLE process){FILETIME c{},e{},k{},u{};if(!GetProcessTimes(process,&c,&e,&k,&u))return 0;return (static_cast<unsigned long long>(c.dwHighDateTime)<<32)|c.dwLowDateTime;}
void clean_abandoned_cache(){
    auto root=capture_folder()/L".replay";if(!std::filesystem::exists(root))return;auto attributes=GetFileAttributesW(root.c_str());if(attributes==INVALID_FILE_ATTRIBUTES||(attributes&FILE_ATTRIBUTE_REPARSE_POINT))throw std::runtime_error("Replay cache cannot be a linked/reparse folder");
    for(const auto& entry:std::filesystem::directory_iterator(root))try{auto attr=GetFileAttributesW(entry.path().c_str());if(attr==INVALID_FILE_ATTRIBUTES||(attr&FILE_ATTRIBUTE_REPARSE_POINT)||!entry.is_directory())continue;auto marker=entry.path()/L".owner.dat";auto rows=decode(read_shared_file(marker,16384));if(rows.size()!=1||rows[0].size()!=4||rows[0][0]!="replay-cache"||rows[0][1]!="1")continue;auto id=std::stoull(rows[0][2]);if(id<=4||id>MAXDWORD)continue;auto prefix=std::to_wstring(id)+L"-",name=entry.path().filename().wstring();if(name.rfind(L"buffer-"+prefix,0)!=0&&name.rfind(L"export-"+prefix,0)!=0)continue;HANDLE process=OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION|SYNCHRONIZE,FALSE,static_cast<DWORD>(id));bool abandoned=false;if(process){auto birth=process_birth(process);abandoned=WaitForSingleObject(process,0)==WAIT_OBJECT_0||(birth&&birth!=std::stoull(rows[0][3]));CloseHandle(process);}else abandoned=GetLastError()==ERROR_INVALID_PARAMETER;if(!abandoned)continue;bool owned=true;for(const auto& file:std::filesystem::directory_iterator(entry.path())){auto flags=GetFileAttributesW(file.path().c_str());if(flags==INVALID_FILE_ATTRIBUTES||(flags&(FILE_ATTRIBUTE_REPARSE_POINT|FILE_ATTRIBUTE_DIRECTORY))){owned=false;break;}auto filename=file.path().filename().wstring(),stem=file.path().stem().wstring();if(filename==L".owner.dat")continue;if(file.path().extension()!=L".mp4"||stem.empty()||stem.find_first_not_of(L"0123456789")!=std::wstring::npos){owned=false;break;}}if(owned)std::filesystem::remove_all(entry.path());}catch(const std::exception&){                                                   }
}
std::filesystem::path unique_folder(const wchar_t* category){static std::atomic<unsigned long long> sequence{0};auto base=capture_folder()/L".replay";std::filesystem::create_directories(base);if(GetFileAttributesW(base.c_str())&FILE_ATTRIBUTE_REPARSE_POINT)throw std::runtime_error("Replay cache cannot be linked");auto folder=base/(std::wstring(category)+L"-"+std::to_wstring(GetCurrentProcessId())+L"-"+std::to_wstring(GetTickCount64())+L"-"+std::to_wstring(++sequence));if(!std::filesystem::create_directory(folder))throw std::runtime_error("Replay folder collision");atomic_write(folder/L".owner.dat",encode({{"replay-cache","1",std::to_string(GetCurrentProcessId()),std::to_string(process_birth(GetCurrentProcess()))}}));return folder;}
}

Replay::~Replay(){stop();}
double Replay::available()const{std::lock_guard<std::mutex> lock(mutex);return std::min(static_cast<double>(capacity),retained);}
std::string Replay::error()const{std::lock_guard<std::mutex> lock(mutex);return problem;}
void Replay::stop(){stopping=true;wake.notify_all();if(worker.joinable())worker.join();running=false;ready_to_save=false;std::lock_guard<std::mutex> lock(mutex);retained=0;}
void Replay::start(const CaptureOptions& original,unsigned seconds){
    if(seconds!=30&&seconds!=60&&seconds!=120)throw std::runtime_error("Choose a 30, 60 or 120 second replay buffer");if(active())throw std::runtime_error("Replay buffer is already running");validate_capture_options(original);stop();stopping=false;running=true;ready_to_save=false;{std::lock_guard<std::mutex> lock(mutex);capacity=seconds;problem.clear();retained=0;request.reset();}
    worker=std::thread([this,original]{
        std::filesystem::path folder;Recorder recorder;struct Segment{std::filesystem::path file;double duration;unsigned long long bytes;};std::deque<Segment> segments;unsigned sequence=0;double duration=0;unsigned long long bytes=0;std::shared_ptr<Request> processing;
        auto fail_pending=[&](const std::string& text){std::shared_ptr<Request> pending;{std::lock_guard<std::mutex> lock(mutex);pending=std::move(request);}if(pending)pending->result.set_exception(std::make_exception_ptr(std::runtime_error(text)));};
        try{clean_abandoned_cache();folder=unique_folder(L"buffer");auto start_chunk=[&]{auto options=original;options.seconds=8;options.output=folder/(std::to_wstring(++sequence)+L".mp4");recorder.start(options);};start_chunk();
            while(!stopping){auto& pending=processing;{std::unique_lock<std::mutex> lock(mutex);wake.wait_for(lock,std::chrono::milliseconds(80),[&]{return stopping.load()||request!=nullptr;});pending=std::move(request);}if(stopping){if(pending)pending->result.set_exception(std::make_exception_ptr(std::runtime_error("Replay stopped")));pending.reset();break;}if((recorder.elapsed()>=1&&recorder.frames()>0)||!segments.empty())ready_to_save=true;if(recorder.active()&&!pending)continue;
                                                                                          
                                                                                          
                if(!recorder.active()||recorder.frames()>0){
                recorder.stop();if(!recorder.error().empty())throw std::runtime_error(recorder.error());auto file=recorder.file();double length=recorder.frames()?media_duration(file):0;if(length>.01){auto size=std::filesystem::file_size(file);segments.push_back({file,length,size});duration+=length;bytes+=size;}else{std::error_code ec;std::filesystem::remove(file,ec);}start_chunk();
                while(segments.size()>1&&(duration-segments.front().duration>=capacity||bytes>96ULL*1024*1024)){duration-=segments.front().duration;bytes-=segments.front().bytes;std::filesystem::remove(segments.front().file);segments.pop_front();}{std::lock_guard<std::mutex> lock(mutex);retained=duration;}}
                if(pending){try{if(segments.empty())throw std::runtime_error("Replay needs recorded frames before saving");auto snapshot=std::make_shared<Snapshot>();snapshot->folder=unique_folder(L"export");double needed=0;size_t first=segments.size();while(first>0&&needed<pending->seconds){--first;needed+=segments[first].duration;}for(size_t i=first;i<segments.size();++i){auto target=snapshot->folder/(std::to_wstring(i-first)+L".mp4");std::error_code ec;std::filesystem::create_hard_link(segments[i].file,target,ec);if(ec)std::filesystem::copy_file(segments[i].file,target);snapshot->files.push_back(target);}pending->result.set_value(snapshot);}catch(...){pending->result.set_exception(std::current_exception());}pending.reset();}
            }
        }catch(const std::exception& e){{std::lock_guard<std::mutex> lock(mutex);problem=e.what();}if(processing){try{processing->result.set_exception(std::current_exception());}catch(const std::future_error&){}processing.reset();}fail_pending(e.what());}recorder.stop();fail_pending("Replay stopped");if(!folder.empty()){std::error_code ec;std::filesystem::remove_all(folder,ec);}running=false;ready_to_save=false;
    });
}
std::filesystem::path Replay::save(unsigned seconds,std::atomic<bool>& cancel){
    if(seconds<1||seconds>120)throw std::runtime_error("Replay save must be 1 to 120 seconds");std::unique_lock<std::mutex> only(saving,std::try_to_lock);if(!only.owns_lock())throw std::runtime_error("A replay export is already running");auto pending=std::make_shared<Request>();pending->seconds=seconds;auto future=pending->result.get_future();{std::lock_guard<std::mutex> lock(mutex);if(!running||stopping)throw std::runtime_error("Start replay buffering before saving");if(!ready_to_save)throw std::runtime_error("Replay is warming up; wait for recorded frames before saving");if(request)throw std::runtime_error("Replay save is already pending");request=pending;}wake.notify_all();while(future.wait_for(std::chrono::milliseconds(100))!=std::future_status::ready){if(!running){if(future.wait_for(std::chrono::milliseconds(0))==std::future_status::ready)break;auto reason=error();throw std::runtime_error(reason.empty()?"Replay buffer stopped before the clip could be saved":"Replay capture failed: "+reason);}}auto snapshot=future.get();if(cancel)throw std::runtime_error("Replay export canceled; buffer is still running");return export_replay(snapshot->files,seconds,cancel);
}
}
